"""Tests for the evolution engine, including table-driven rules.

Run with: python -m pytest tests/
"""
import random

import pytest

from lifeplot.game_of_life import NEIGH_ORDER, PatternEvolver, table_from_hex

GLIDER = {(1, 0), (2, 1), (0, 2), (1, 2), (2, 2)}

# The first plotted automon (apgcode xq4_1vl0o88o0lv1z0aa7y07aazy07w7),
# rule b2kn3-q4cinqz5knrs1e3eikny4-ajtz6c7e — table generated by the
# automons repo with lifelib as the oracle.
AUTOMON_RLE_CELLS = "bo8bo$bo8bo2$4ob2ob4o$2o8b2o2$bob2o2b2obo$bob2o2b2obo$bobo4bobo$bo8bo$3bo4bo$4bo2bo$3bob2obo$4bo2bo!"


def parse_body(body):
    cells = set()
    x = y = 0
    count = ""
    for ch in body:
        if ch.isdigit():
            count += ch
            continue
        n = int(count) if count else 1
        count = ""
        if ch == "b":
            x += n
        elif ch == "o":
            for _ in range(n):
                cells.add((x, y))
                x += 1
        elif ch == "$":
            y += n
            x = 0
        elif ch == "!":
            break
    return cells


def conway_table():
    """B3/S23 as a 512-entry table, built independently of _step."""
    table = [0] * 512
    for idx in range(512):
        centre = idx >> 8
        n = bin(idx & 0xFF).count("1")
        table[idx] = 1 if (n == 3 or (centre and n == 2)) else 0
    return table


def test_table_from_hex_roundtrip():
    table = conway_table()
    chars = []
    for i in range(0, 512, 4):
        nibble = table[i] | table[i + 1] << 1 | table[i + 2] << 2 | table[i + 3] << 3
        chars.append("%x" % nibble)
    assert table_from_hex("".join(chars)) == table


def test_table_from_hex_rejects_bad_length():
    with pytest.raises(ValueError):
        table_from_hex("cafe")


def test_neigh_order_is_eight_unique_neighbours():
    assert len(NEIGH_ORDER) == 8
    assert len(set(NEIGH_ORDER)) == 8
    assert (0, 0) not in NEIGH_ORDER


def test_conway_table_matches_builtin_step_on_random_patterns():
    """The table path and the hardcoded Conway path must agree exactly."""
    table = conway_table()
    rng = random.Random(42)
    for _ in range(25):
        cells = {(rng.randrange(20), rng.randrange(20)) for _ in range(rng.randrange(1, 60))}
        assert PatternEvolver._step(cells, table) == PatternEvolver._step(cells)


def test_conway_default_glider_period():
    ev = PatternEvolver()
    gens = ev.evolve(GLIDER)
    assert ev.get_period() == 4
    assert len(gens) == 4


def test_table_none_is_default():
    assert PatternEvolver().rule_table is None


def test_automon_ship_flies_with_its_table():
    """Regression: the first plotted isotropic ship is period 4 and
    translates itself (uses plotter/rle/automon_p4.table; skips if it is missing).
    """
    import os
    here = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    table_path = os.path.join(here, "rle", "automon_p4.table")
    if not os.path.exists(table_path):
        pytest.skip("automon_p4.table not generated")
    with open(table_path) as f:
        table = table_from_hex(f.read())
    cells = parse_body(AUTOMON_RLE_CELLS)
    ev = PatternEvolver(rule_table=table)
    gens = ev.evolve(cells)
    assert ev.get_period() == 4
    g4 = PatternEvolver._step(gens[-1], table)
    norm = PatternEvolver._normalize_pattern
    assert norm(g4) == norm(gens[0])
